// page/03-errors.js
// Inline validation: messages and character counters.
// Generated by linkedin/automation/scripts/split-page-helpers.py from 00-context.js.

Object.assign(helpers, {
      // A control that the page rejects: the inline message, and the
      // "51/20" counter LinkedIn prints next to it.
      controlError(element) {
        if (!element) return { message: '', over: false, max: 0 };
        const ids = (element.getAttribute('aria-describedby') || '').split(/\s+/).filter(Boolean);
        const nodes = ids.map((id) => document.getElementById(id)).filter(Boolean);
        const row = element.parentElement;
        if (row) {
          nodes.push(
            ...Array.from(
              row.querySelectorAll('[role="alert"], .artdeco-inline-feedback--error, .artdeco-inline-message'),
            ),
          );
        }
        const texts = nodes.map((node) => (node.innerText || '').trim()).filter(Boolean);
        const counterText = texts.find((text) => /^\d+\s*\/\s*\d+$/.test(text)) || '';
        const written = texts.find((text) => /^\d+\s+of\s+\d+\s+characters?$/i.test(text)) || '';
        const message =
          texts.find(
            (text) =>
              !/^\d+\s*(\/|\s+of\s+)\s*\d+\s*(characters?)?$/i.test(text) &&
              /invalid|not valid|too long|must (be|contain)|only (numbers|digits)|please (enter|select|provide)/i.test(
                text,
              ),
          ) || '';
        const counter =
          counterText.match(/^(\d+)\s*\/\s*(\d+)$/) ||
          written.match(/^(\d+)\s+of\s+(\d+)\s+characters?$/i);
        const over = counter ? Number(counter[1]) > Number(counter[2]) : false;
        const max = counter ? Number(counter[2]) : 0;
        if (element.getAttribute('aria-invalid') === 'true' && !message) {
          return { message: 'invalid input', over, max };
        }
        return { message, over, max };
      },
      validationErrors(scope) {
        const root = scope || document;
        const known = Array.from(
          root.querySelectorAll('.artdeco-inline-message, [role="alert"], .jobs-application-form__error'),
        )
          .map((node) => (node.innerText || '').trim())
          .filter(Boolean);
        const inline = Array.from(root.querySelectorAll('*'))
          .filter((node) => node.children.length === 0)
          .map((node) => (node.innerText || '').trim())
          .filter(
            (text) =>
              text &&
              text.length < 70 &&
              /this field is required|is required|invalid input|please (enter|select|choose|provide|upload|confirm)/i.test(text),
          );
        return [...new Set([...known, ...inline])].slice(0, 6);
      },
      // The control an error message belongs to. A row can hold several
      // controls, so the described-by link wins, then the nearest control
      // before the message in document order.
      controlsWithErrors(scope) {
        const root = scope || document;
        const out = [];
        const seen = new Set();
        const controls = Array.from(root.querySelectorAll('input, select, textarea'));
        for (const node of Array.from(root.querySelectorAll('*'))) {
          if (node.children.length !== 0) continue;
          const text = (node.innerText || '').trim();
          if (!text || text.length > 70 || !/required|invalid|please|too long/i.test(text)) continue;

          let control = null;
          if (node.id) {
            control = root.querySelector(`[aria-describedby~="${CSS.escape(node.id)}"]`);
          }
          if (!control) {
            let container = node.parentElement;
            for (let depth = 0; depth < 5 && container && !control; depth += 1) {
              const inside = Array.from(container.querySelectorAll('input, select, textarea'));
              if (inside.length === 1) control = inside[0];
              container = container.parentElement;
            }
          }
          if (!control) {
            control =
              controls
                .filter((item) => item.compareDocumentPosition(node) & Node.DOCUMENT_POSITION_FOLLOWING)
                .pop() || null;
          }
          if (!control) continue;

          const key = control.id || control.name || helpers.labelText(control);
          if (!key || seen.has(key)) continue;
          seen.add(key);
          out.push({
            label: helpers.labelText(control) || helpers.groupLabel(control),
            type: control.type,
            id: control.id,
            reason: 'invalid_value',
            value: String(control.value || '').slice(0, 40),
            // A described-by message can outlive the value that caused it.
            // Only these three marks mean the control is rejected right now.
            valid: typeof control.checkValidity === 'function' ? control.checkValidity() : true,
            over: helpers.controlError(control).over,
            ariaInvalid: control.getAttribute('aria-invalid') === 'true',
          });
        }
        return out;
      },
});
